import { HttpClient, NonNullablePaths } from '@wix/sdk-types';
import {
  AssignRoleApplicationErrors,
  AssignRoleResponse,
  GetRolesResponse,
  QueryRolesOptions,
  QueryRolesResponse,
  UnassignRoleResponse,
  UnassignRoleValidationErrors,
  assignRole as universalAssignRole,
  getRoles as universalGetRoles,
  queryRoles as universalQueryRoles,
  unassignRole as universalUnassignRole,
} from './members-v1-role-authorization.universal.js';

export const __metadata = { PACKAGE_NAME: '@wix/members' };

export function assignRole(httpClient: HttpClient): AssignRoleSignature {
  return (memberId: string, roleKey: string) =>
    universalAssignRole(
      memberId,
      roleKey,
      // @ts-ignore
      { httpClient }
    );
}

interface AssignRoleSignature {
  /**
   * Assigns a role to a member.
   *
   * Use roles to grant members special permissions on the site.
   * The role must exist before it can be assigned — create a role first using
   * [Create Member Role Definition](https://dev.wix.com/docs/rest/crm/members-contacts/members/member-role-definition-v1/create-member-role-definition).
   *
   * Blockable roles cannot be assigned to blocked members.
   * @param - ID of the member to assign the role to.
   * @param - Key of the role to assign.
   */
  (memberId: string, roleKey: string): Promise<
    NonNullablePaths<AssignRoleResponse, `roleKey`, 2> & {
      __applicationErrorsType?: AssignRoleApplicationErrors;
    }
  >;
}

export function unassignRole(httpClient: HttpClient): UnassignRoleSignature {
  return (memberId: string, roleKey: string) =>
    universalUnassignRole(
      memberId,
      roleKey,
      // @ts-ignore
      { httpClient }
    );
}

interface UnassignRoleSignature {
  /**
   * Removes a role from a member.
   *
   * To retrieve the roles currently assigned to a member, call
   * [Get Roles](https://dev.wix.com/docs/rest/crm/members-contacts/members/role-v1/get-roles).
   * @param - ID of the member to remove the role from.
   * @param - Key of the role to remove.
   */
  (memberId: string, roleKey: string): Promise<
    NonNullablePaths<UnassignRoleResponse, `roleKey`, 2> & {
      __validationErrorsType?: UnassignRoleValidationErrors;
    }
  >;
}

export function getRoles(httpClient: HttpClient): GetRolesSignature {
  return (memberId: string) =>
    universalGetRoles(
      memberId,
      // @ts-ignore
      { httpClient }
    );
}

interface GetRolesSignature {
  /**
   * Retrieves all roles assigned to a member.
   *
   * To retrieve roles for multiple members at once, use
   * [Query Roles](https://dev.wix.com/docs/rest/crm/members-contacts/members/role-v1/query-roles).
   * @param - ID of the member whose roles to retrieve.
   */
  (memberId: string): Promise<
    NonNullablePaths<
      GetRolesResponse,
      `roles` | `roles.${number}.roleKey` | `roles.${number}.title`,
      4
    >
  >;
}

export function queryRoles(httpClient: HttpClient): QueryRolesSignature {
  return (options?: QueryRolesOptions) =>
    universalQueryRoles(
      options,
      // @ts-ignore
      { httpClient }
    );
}

interface QueryRolesSignature {
  /**
   * Retrieves roles assigned to members that match a given filter.
   *
   * The response maps each matching member ID to their list of roles.
   * To retrieve roles for a single known member, use
   * [Get Roles](https://dev.wix.com/docs/rest/crm/members-contacts/members/role-v1/get-roles).
   */
  (options?: QueryRolesOptions): Promise<QueryRolesResponse>;
}

export {
  ActionEvent,
  AssignRoleRequest,
  AssignRoleResponse,
  DomainEvent,
  DomainEventBodyOneOf,
  Empty,
  EntityCreatedEvent,
  EntityDeletedEvent,
  EntityUpdatedEvent,
  GetRolesRequest,
  GetRolesResponse,
  MemberRole,
  PolicyAssignedToContributor,
  PolicyRemovedFromContributor,
  PolicyUpdatedForContributor,
  Query,
  QueryRolesOptions,
  QueryRolesRequest,
  QueryRolesResponse,
  RestoreInfo,
  Role,
  UnassignRoleRequest,
  UnassignRoleResponse,
} from './members-v1-role-authorization.universal.js';
