export const onBadgeAssigned = EventDefinition(
  'wix.badges.v3.badge_badge_assigned',
  true,
  (event: BadgeAssignedEnvelope) =>
    renameKeysFromRESTResponseToSDKResponse(
      transformPaths(event, [
        {
          transformFn: transformRESTTimestampToSDKTimestamp,
          paths: [{ path: 'metadata.eventTime' }],
        },
      ])
    )
)<BadgeAssignedEnvelope>();
export const onBadgeUnassigned = EventDefinition(
  'wix.badges.v3.badge_badge_unassigned',
  true,
  (event: BadgeUnassignedEnvelope) =>
    renameKeysFromRESTResponseToSDKResponse(
      transformPaths(event, [
        {
          transformFn: transformRESTTimestampToSDKTimestamp,
          paths: [{ path: 'metadata.eventTime' }],
        },
      ])
    )
)<BadgeUnassignedEnvelope>();

