export function createCustomField(
  httpClient: HttpClient
): CreateCustomFieldSignature {
  return (field: NonNullablePaths<CustomField, `name`, 2>) =>
    universalCreateCustomField(
      field,
      // @ts-ignore
      { httpClient }
    );
}

interface CreateCustomFieldSignature {
  /**
   * Creates a custom field.
   * @param - Custom field to create.
   * @returns Created custom field.
   */
  (field: NonNullablePaths<CustomField, `name`, 2>): Promise<
    NonNullablePaths<
      CustomField,
      | `defaultPrivacy`
      | `fieldType`
      | `socialType`
      | `fieldOrigin`
      | `appliesTo`
      | `section`,
      2
    > & {
      __applicationErrorsType?: CreateCustomFieldApplicationErrors;
    }
  >;
}

