export function listCustomFields(
  httpClient: HttpClient
): ListCustomFieldsSignature {
  return (options?: ListCustomFieldsOptions) =>
    universalListCustomFields(
      options,
      // @ts-ignore
      { httpClient }
    );
}

interface ListCustomFieldsSignature {
  /**
   * Retrieves a list of custom fields and fields provided by Members Area, given the provided paging.
   *
   * The fields are ordered by section in the following sequence:
   * - `GENERAL`
   * - `DISPLAY_INFO`
   * - `SOCIAL`
   *
   * The fields in the same section are ordered by the field creation date.
   *
   * To change the order of fields in sections, call Update Custom Fields Order.
   */
  (options?: ListCustomFieldsOptions): Promise<
    NonNullablePaths<
      ListCustomFieldsResponse,
      | `fields`
      | `fields.${number}.defaultPrivacy`
      | `fields.${number}.fieldType`
      | `fields.${number}.socialType`
      | `fields.${number}.fieldOrigin`
      | `fields.${number}.appliesTo`
      | `fields.${number}.section`,
      4
    >
  >;
}

