interface HideCustomFieldSignature {
  /**
   * Hides a custom field from the custom fields list, yet it's still available as a [suggested field](https://dev.wix.com/docs/rest/crm/members-contacts/members/custom-fields/custom-field-suggestions/introduction)
   * to add later.
   *
   * The related contacts custom field will still be available in the [Contact List](https://support.wix.com/en/article/wix-contacts-managing-your-contact-list).
   * @param - ID of the custom field to hide.
   * @param - Revision number.
   */
  (_id: string, revision: string): Promise<void>;
}

