function customQueryMembers(httpClient: HttpClient) {
  const router = createQueryOverloadRouter({
    builderQueryFunction: (options?: QueryMembersOptions) =>
      publicQueryMembers(httpClient)(options),
    typedQueryFunction: (query: MemberQuery, options?: QueryMembersOptions) =>
      publicTypedQueryMembers(httpClient)(query, options),
    hasOptionsParameter: true,
  });

  function overloadedQuery(
    query: MemberQuery,
    options?: QueryMembersOptions
  ): ReturnType<typeof universalTypedQueryMembers>;
  function overloadedQuery(options?: QueryMembersOptions): MembersQueryBuilder;
  function overloadedQuery(
    queryOrOptions?: MemberQuery | QueryMembersOptions,
    options?: QueryMembersOptions
  ): any {
    return router(...arguments);
  }

  return overloadedQuery;
}

